 ## 4. 核心代码
+
+本节选取项目中最能体现检索系统核心逻辑的代码进行说明，主要包括索引结构定义、文本规范化与倒排索引构建、五种检索模式、上下文提取，以及字符串匹配算法性能测试。为便于阅读，下列代码在保留原有实现逻辑的基础上补充了更充分的中文注释。
+
+### 4.1 索引结构与搜索请求
+
+`Index` 是整个搜索引擎的基础数据结构。每一次词项出现都被记录为三元组：所在书籍、所在行、行内词序。相比只记录书籍编号，加入行号和词序后，系统不仅可以做普通关键词检索，还可以支持短语检索、近邻检索和上下文展示。
+
+```cpp
+// 单个词项在全文中的精确位置。
+// book_id：词项所在书籍在 books 数组中的下标；
+// line：词项所在原文行号；
+// word_idx：词项在该行分词后的序号。
+struct Index {
+    size_t book_id;
+    size_t line;
+    size_t word_idx;
+};
+
+// 前端 TUI 通过 SearchMode 指定本次检索使用哪一种组合逻辑。
+enum class SearchMode {
+    Or,      // 任意关键词出现即可命中
+    And,     // 所有关键词都必须在同一本书中出现
+    Phrase,  // 多个关键词必须在同一行连续出现
+    Not,     // 第一个词必须出现，其余词所在书籍被排除
+    Near,    // 两个关键词必须在同一行且距离不超过阈值
+};
+
+// 一次搜索请求由检索模式、原始查询字符串和 NEAR 距离组成。
+struct SearchRequest {
+    SearchMode mode = SearchMode::Or;
+    std::string query;
+    size_t near_distance = 5;
+};
+```
+
+### 4.2 文本规范化与分词
+
+不同书籍中的英文单词可能带有大小写、逗号、句号、引号等差异。若直接建立索引，`Harry`、`harry` 和 `Harry,` 会被当作三个不同词项，影响检索结果。因此建索引和解析查询时都先调用同一套规范化函数：只保留字母和数字，并统一转为小写。
+
+```cpp
+namespace {
+
+std::string normalize_word(std::string_view word) {
+    std::string normalized;
+    normalized.reserve(word.size());
+
+    // 逐字符处理原始单词：
+    // 1. isalnum 过滤标点符号；
+    // 2. tolower 统一大小写；
+    // 3. 使用 unsigned char 避免 char 为负数时传给 ctype 函数产生未定义行为。
+    for (unsigned char ch : word) {
+        if (std::isalnum(ch) != 0) {
+            normalized.push_back(static_cast<char>(std::tolower(ch)));
+        }
+    }
+
+    return normalized;
+}
+
+std::vector<std::string> tokenize(std::string_view text) {
+    std::vector<std::string> words;
+    std::istringstream stream{std::string{text}};
+
+    // 先按空白字符拆分，再对每个原始片段做规范化。
+    // 若规范化后为空，说明该片段只包含标点，应当丢弃。
+    for (std::string raw_word; stream >> raw_word;) {
+        std::string word = normalize_word(raw_word);
+        if (!word.empty()) {
+            words.push_back(std::move(word));
+        }
+    }
+
+    return words;
+}
+
+}  // namespace
+```
+
+### 4.3 倒排索引构建
+
+加载书籍后，搜索引擎逐行分词，并把每个词映射到它出现过的所有位置。`inverted_index` 的类型为 `unordered_map<string, vector<Index>>`，即“词项 -> 出现位置列表”。同时，`word_counts` 记录词频，用于在界面中展示高频词。
+
+```cpp
+void SearchEngine::add_book(Book book) {
+    // 当前书籍的编号就是插入 books 前的数组长度。
+    // 后续所有 Index 都用这个编号指向该书。
+    const size_t book_id = books.size();
+
+    // 遍历书籍中的每一行，保留 line_id 以便后续定位上下文。
+    for (size_t line_id = 0; line_id < book.lines.size(); ++line_id) {
+        const std::vector<std::string> words = tokenize(book.lines[line_id]);
+
+        // word_idx 表示该词在当前行中的位置，Phrase 和 NEAR 检索都依赖它。
+        for (size_t word_idx = 0; word_idx < words.size(); ++word_idx) {
+            const std::string& word = words[word_idx];
+
+            // 将“词项 -> 位置”加入倒排索引。
+            // 同一个词可能出现多次，因此 value 是 vector<Index>。
+            inverted_index[word].emplace_back(Index{
+                .book_id = book_id,
+                .line = line_id,
+                .word_idx = word_idx,
+            });
+
+            // 维护词频统计，供 get_top_words 使用。
+            ++word_counts[word];
+        }
+    }
+
+    // 索引构建完成后再保存书籍对象，保证 book_id 与 books 下标一致。
+    books.push_back(std::move(book));
+}
+```
+
+### 4.4 检索模式分发
+
+TUI 层只需要构造 `SearchRequest`，后端根据 `mode` 分发到对应算法。分发后再次检查 `book_id` 是否有效，避免异常索引进入结果展示阶段。
+
+```cpp
+std::vector<Index> SearchEngine::search_with_context(const SearchRequest& request) const {
+    std::vector<Index> matches;
+
+    // 根据用户在界面中选择的模式调用不同检索函数。
+    switch (request.mode) {
+        case SearchMode::Or:
+            matches = search_or(request.query);
+            break;
+        case SearchMode::And:
+            matches = search_and(request.query);
+            break;
+        case SearchMode::Phrase:
+            matches = search_phrase(request.query);
+            break;
+        case SearchMode::Not:
+            matches = search_not(request.query);
+            break;
+        case SearchMode::Near:
+            matches = search_near(request.query, request.near_distance);
+            break;
+    }
+
+    std::vector<Index> hits;
+    hits.reserve(matches.size());
+
+    // 过滤无效 book_id，保证后续 get_context 可以安全访问 books。
+    for (const Index& index : matches) {
+        if (index.book_id >= books.size()) {
+            continue;
+        }
+        hits.push_back(index);
+    }
+
+    return hits;
+}
+```
+
+### 4.5 OR 与 AND 检索
+
+`OR` 检索返回任一查询词出现的位置；`AND` 检索先判断哪些书同时包含所有查询词，再返回这些书中相关词项的位置。两者最后都按书籍、行号、词序排序，使结果展示顺序稳定。
+
+```cpp
+std::vector<Index> SearchEngine::search_or(std::string_view query) const {
+    std::vector<std::string> words;
+    std::unordered_set<std::string> seen_words;
+
+    // 查询词同样使用 tokenize，保证与建索引时的规范化规则一致。
+    // seen_words 用来去重，避免同一个查询词重复合并 posting list。
+    for (std::string& word : tokenize(query)) {
+        if (seen_words.insert(word).second) {
+            words.emplace_back(std::move(word));
+        }
+    }
+
+    std::vector<Index> matches;
+
+    // OR：只要某个词存在，就把该词的所有出现位置加入结果。
+    for (const std::string& word : words) {
+        const auto found = inverted_index.find(word);
+        if (found != inverted_index.end()) {
+            matches.insert(matches.end(), found->second.begin(), found->second.end());
+        }
+    }
+
+    // 按 book_id、line、word_idx 排序，便于界面按原文顺序展示。
+    std::ranges::sort(matches, {}, cmpr);
+    return matches;
+}
+
+std::vector<Index> SearchEngine::search_and(std::string_view query) const {
+    std::vector<std::string> words;
+    std::unordered_set<std::string> seen_words;
+
+    for (std::string& word : tokenize(query)) {
+        if (seen_words.insert(word).second) {
+            words.emplace_back(std::move(word));
+        }
+    }
+
+    if (words.empty()) {
+        return {};
+    }
+
+    // 统计每本书命中了多少个不同查询词。
+    std::unordered_map<size_t, size_t> book_match_counts;
+
+    for (const std::string& word : words) {
+        const auto found = inverted_index.find(word);
+        if (found == inverted_index.end()) {
+            // AND 检索中，只要有一个词不存在，整体结果必为空。
+            return {};
+        }
+
+        // 同一个词在一本书中可能出现很多次，
+        // 但判断 AND 条件时，一本书对一个词只计一次。
+        std::unordered_set<size_t> matched_books;
+        for (const Index& index : found->second) {
+            matched_books.emplace(index.book_id);
+        }
+
+        for (size_t book_id : matched_books) {
+            book_match_counts[book_id]++;
+        }
+    }
+
+    // 只有命中词数等于查询词总数的书籍才满足 AND 条件。
+    std::unordered_set<size_t> matched_books;
+    for (const auto& [book_id, count] : book_match_counts) {
+        if (count == words.size()) {
+            matched_books.insert(book_id);
+        }
+    }
+
+    std::vector<Index> matches;
+    for (const std::string& word : words) {
+        const auto& indices = inverted_index.at(word);
+        for (const Index& index : indices) {
+            if (matched_books.contains(index.book_id)) {
+                matches.push_back(index);
+            }
+        }
+    }
+
+    std::ranges::sort(matches, {}, cmpr);
+    return matches;
+}
+```
+
+### 4.6 Phrase、NOT 与 NEAR 检索
+
+`Phrase` 和 `NEAR` 都利用 `Index` 中的行号和行内词序。短语检索要求词项连续；近邻检索要求两个词在同一行且距离不超过阈值。`NOT` 检索则将第一个词作为保留词，将后续词出现过的书籍全部排除。
+
+```cpp
+std::vector<Index> SearchEngine::search_phrase(std::string_view query) const {
+    const std::vector<std::string> words = tokenize(query);
+    if (words.empty()) {
+        return {};
+    }
+
+    // 短语匹配从第一个词的每个出现位置开始尝试。
+    const auto first_word = inverted_index.find(words.front());
+    if (first_word == inverted_index.end()) {
+        return {};
+    }
+
+    std::vector<Index> matches;
+    for (const Index& start : first_word->second) {
+        std::vector<Index> phrase_match{start};
+        bool is_phrase = true;
+
+        // 第 offset 个词必须出现在同一本书、同一行，
+        // 并且 word_idx == start.word_idx + offset。
+        for (size_t offset = 1; offset < words.size(); ++offset) {
+            const auto found = inverted_index.find(words[offset]);
+            if (found == inverted_index.end()) {
+                return {};
+            }
+
+            const auto next = std::ranges::find_if(found->second, [&](const Index& index) {
+                return index.book_id == start.book_id && index.line == start.line &&
+                       index.word_idx == start.word_idx + offset;
+            });
+
+            if (next == found->second.end()) {
+                is_phrase = false;
+                break;
+            }
+
+            phrase_match.push_back(*next);
+        }
+
+        if (is_phrase) {
+            matches.insert(matches.end(), phrase_match.begin(), phrase_match.end());
+        }
+    }
+
+    std::ranges::sort(matches, {}, cmpr);
+    return matches;
+}
+
+std::vector<Index> SearchEngine::search_not(std::string_view query) const {
+    const std::vector<std::string> words = tokenize(query);
+    if (words.empty()) {
+        return {};
+    }
+
+    // 第一个词是需要保留的词项。
+    const auto first_word = inverted_index.find(words.front());
+    if (first_word == inverted_index.end()) {
+        return {};
+    }
+
+    // 后续词项出现过的书籍都要被排除。
+    std::unordered_set<size_t> excluded_books;
+    for (auto word = std::next(words.begin()); word != words.end(); ++word) {
+        const auto found = inverted_index.find(*word);
+        if (found == inverted_index.end()) {
+            continue;
+        }
+
+        for (const Index& index : found->second) {
+            excluded_books.insert(index.book_id);
+        }
+    }
+
+    // 只保留第一个词中不属于 excluded_books 的出现位置。
+    std::vector<Index> matches;
+    for (const Index& index : first_word->second) {
+        if (!excluded_books.contains(index.book_id)) {
+            matches.push_back(index);
+        }
+    }
+
+    std::ranges::sort(matches, {}, cmpr);
+    return matches;
+}
+
+std::vector<Index> SearchEngine::search_near(std::string_view query, size_t dis) const {
+    const std::vector<std::string> words = tokenize(query);
+    if (words.empty()) {
+        return {};
+    }
+
+    // 只有一个词时，NEAR 退化为普通 OR 检索。
+    if (words.size() == 1) {
+        return search_or(query);
+    }
+
+    const std::string& word1 = words[0];
+    const std::string& word2 = words[1];
+
+    const auto first_word = inverted_index.find(word1);
+    const auto second_word = inverted_index.find(word2);
+    if (first_word == inverted_index.end() || second_word == inverted_index.end()) {
+        return {};
+    }
+
+    std::vector<Index> matches;
+    for (const Index& first : first_word->second) {
+        for (const Index& second : second_word->second) {
+            // NEAR 要求两个词出现在同一本书的同一行。
+            if (first.book_id != second.book_id || first.line != second.line) {
+                continue;
+            }
+
+            // 计算两个词在行内的绝对距离。
+            const size_t distance = first.word_idx > second.word_idx
+                                        ? first.word_idx - second.word_idx
+                                        : second.word_idx - first.word_idx;
+            if (distance <= dis) {
+                matches.push_back(first);
+                matches.push_back(second);
+            }
+        }
+    }
+
+    std::ranges::sort(matches, {}, cmpr);
+    return matches;
+}
+```
+
+### 4.7 上下文定位
+
+搜索结果只给出命中位置还不够，界面需要展示命中段落及其前后段落。因此系统以空白行为段落边界，从命中行向前、向后扩展，得到前一段、当前段和后一段。
+
+```cpp
+Context get_context_range(const std::vector<Book>& books, const Index& idx) {
+    if (idx.book_id >= books.size()) {
+        return {};
+    }
+    const Book& book = books[idx.book_id];
+
+    // 如果命中行越界或本身为空白行，则无法形成有效上下文。
+    if (idx.line >= book.lines.size() || is_blank_line(book.lines[idx.line])) {
+        return {};
+    }
+
+    // 从命中行向上找到当前段落起点。
+    size_t cur_begin = idx.line;
+    while (cur_begin > 0 && !is_blank_line(book.lines[cur_begin - 1])) {
+        cur_begin--;
+    }
+
+    // 从命中行向下找到当前段落终点。
+    size_t cur_end = idx.line + 1;
+    while (cur_end < book.lines.size() && !is_blank_line(book.lines[cur_end])) {
+        cur_end++;
+    }
+
+    Context context{
+        .cur = LineRange{.begin = cur_begin, .end = cur_end},
+    };
+
+    // 当前段落之前可能有多个空白行，需要先跳过空白行。
+    size_t prev_end = cur_begin;
+    while (prev_end > 0 && is_blank_line(book.lines[prev_end - 1])) {
+        --prev_end;
+    }
+
+    // 再继续向上找到前一段落的起点。
+    size_t prev_begin = prev_end;
+    while (prev_begin > 0 && !is_blank_line(book.lines[prev_begin - 1])) {
+        --prev_begin;
+    }
+
+    if (prev_begin < prev_end) {
+        context.prev = LineRange{.begin = prev_begin, .end = prev_end};
+    }
+
+    // 同理，先跳过当前段落之后的空白行，再定位下一段落范围。
+    size_t next_begin = cur_end;
+    while (next_begin < book.lines.size() && is_blank_line(book.lines[next_begin])) {
+        ++next_begin;
+    }
+
+    size_t next_end = next_begin;
+    while (next_end < book.lines.size() && !is_blank_line(book.lines[next_end])) {
+        ++next_end;
+    }
+
+    if (next_begin < next_end) {
+        context.next = LineRange{.begin = next_begin, .end = next_end};
+    }
+
+    return context;
+}
+```
+
+### 4.8 字符串匹配算法测试框架
+
+算法测试模块将不同字符串匹配算法统一包装为 `AlgoResult`，记录算法名称、匹配次数、字符比较次数和耗时。这样 TUI 不需要了解每种算法内部细节，只需要遍历结果数组即可绘制对比界面。
+
+```cpp
+struct AlgoResult {
+    std::string name;       // 算法名称
+    size_t match_count;     // 模式串在主串中出现的次数
+    size_t compare_count;   // 字符级比较次数，用于衡量算法扫描成本
+    long long use_time_ms;  // 实际运行耗时，单位为毫秒
+};
+
+template <typename Fn>
+concept SearchAlgo = requires(Fn&& algo, std::string_view source, std::string_view target) {
+    // 约束传入对象必须能以 (source, target) 调用，并返回 AlgoResult。
+    { std::invoke(std::forward<Fn>(algo), source, target) } -> std::same_as<AlgoResult>;
+};
+
+template <SearchAlgo... Algos>
+auto test_algos(std::string_view source, std::string_view target, Algos&&... algos)
+    -> std::array<AlgoResult, sizeof...(Algos)> {
+    // 使用参数包依次执行所有算法，返回统一结果数组。
+    return {std::invoke(std::forward<Algos>(algos), source, target)...};
+}
+```
+
+### 4.9 KMP 核心实现
+
+KMP 的关键是前缀表 `prefix`。当匹配失败时，模式串不需要整体右移一位，而是根据已经匹配的前缀长度跳转，从而避免主串指针回退。
+
+```cpp
+AlgoResult kmp(std::string_view source, std::string_view target) {
+    const auto begin = Clock::now();
+    size_t compare_count = 0;
+
+    if (target.empty()) {
+        return make_result(__func__, empty_target_matches(source.size()), compare_count, begin);
+    }
+
+    std::vector<size_t> matches;
+    if (target.size() > source.size()) {
+        return make_result(__func__, std::move(matches), compare_count, begin);
+    }
+
+    // prefix[i] 表示 target[0..i] 中最长的“相同真前缀与真后缀”的长度。
+    std::vector<size_t> prefix(target.size(), 0);
+    for (size_t index = 1, matched = 0; index < target.size();) {
+        ++compare_count;
+
+        if (target[index] == target[matched]) {
+            prefix[index] = matched + 1;
+            ++index;
+            ++matched;
+        } else if (matched > 0) {
+            // 构造前缀表时失配，也可以利用已求出的 prefix 回退。
+            matched = prefix[matched - 1];
+        } else {
+            prefix[index] = 0;
+            ++index;
+        }
+    }
+
+    // index 扫描主串，matched 表示当前已经匹配的模式串长度。
+    for (size_t index = 0, matched = 0; index < source.size();) {
+        ++compare_count;
+
+        if (source[index] == target[matched]) {
+            ++index;
+            ++matched;
+
+            if (matched == target.size()) {
+                matches.push_back(index - target.size());
+                // 找到一次完整匹配后继续回退，支持统计重叠匹配。
+                matched = prefix[matched - 1];
+            }
+        } else if (matched > 0) {
+            // 主串 index 不回退，只移动模式串匹配位置。
+            matched = prefix[matched - 1];
