+        // 同一个词在一本书中可能出现很多次，
+        // 但判断 AND 条件时，一本书对一个词只计一次。
+        std::unordered_set<size_t> matched_books;
+        for (const Index& index : found->second) {
+            matched_books.emplace(index.book_id);
