+### 4.7 上下文定位
+
+搜索结果只给出命中位置还不够，界面需要展示命中段落及其前后段落。因此系统以空白行为段落边界，从命中行向前、向后扩展，得到前一段、当前段和后一段。
+
+```cpp
+Context get_context_range(const std::vector<Book>& books, const Index& idx) {
+    if (idx.book_id >= books.size()) {
+        return {};
+    }
+    const Book& book = books[idx.book_id];
+
+    // 如果命中行越界或本身为空白行，则无法形成有效上下文。
+    if (idx.line >= book.lines.size() || is_blank_line(book.lines[idx.line])) {
+        return {};
+    }
+
+    // 从命中行向上找到当前段落起点。
+    size_t cur_begin = idx.line;
+    while (cur_begin > 0 && !is_blank_line(book.lines[cur_begin - 1])) {
+        cur_begin--;
+    }
+
+    // 从命中行向下找到当前段落终点。
+    size_t cur_end = idx.line + 1;
+    while (cur_end < book.lines.size() && !is_blank_line(book.lines[cur_end])) {
+        cur_end++;
+    }
+
+    Context context{
+        .cur = LineRange{.begin = cur_begin, .end = cur_end},
+    };
+
+    // 当前段落之前可能有多个空白行，需要先跳过空白行。
+    size_t prev_end = cur_begin;
+    while (prev_end > 0 && is_blank_line(book.lines[prev_end - 1])) {
+        --prev_end;
+    }
+
+    // 再继续向上找到前一段落的起点。
+    size_t prev_begin = prev_end;
+    while (prev_begin > 0 && !is_blank_line(book.lines[prev_begin - 1])) {
+        --prev_begin;
+    }
+
+    if (prev_begin < prev_end) {
+        context.prev = LineRange{.begin = prev_begin, .end = prev_end};
+    }
+
+    // 同理，先跳过当前段落之后的空白行，再定位下一段落范围。
+    size_t next_begin = cur_end;
+    while (next_begin < book.lines.size() && is_blank_line(book.lines[next_begin])) {
+        ++next_begin;
+    }
+
+    size_t next_end = next_begin;
+    while (next_end < book.lines.size() && !is_blank_line(book.lines[next_end])) {
+        ++next_end;
+    }
+
+    if (next_begin < next_end) {
+        context.next = LineRange{.begin = next_begin, .end = next_end};
+    }
+
+    return context;
+}
+```
