+### 4.9 KMP 核心实现
+
+KMP 的关键是前缀表 `prefix`。当匹配失败时，模式串不需要整体右移一位，而是根据已经匹配的前缀长度跳转，从而避免主串指针回退。
+
+```cpp
+AlgoResult kmp(std::string_view source, std::string_view target) {
+    const auto begin = Clock::now();
+    size_t compare_count = 0;
+
+    if (target.empty()) {
+        return make_result(__func__, empty_target_matches(source.size()), compare_count, begin);
+    }
+
+    std::vector<size_t> matches;
+    if (target.size() > source.size()) {
+        return make_result(__func__, std::move(matches), compare_count, begin);
+    }
+
+    // prefix[i] 表示 target[0..i] 中最长的“相同真前缀与真后缀”的长度。
+    std::vector<size_t> prefix(target.size(), 0);
+    for (size_t index = 1, matched = 0; index < target.size();) {
+        ++compare_count;
+
+        if (target[index] == target[matched]) {
+            prefix[index] = matched + 1;
+            ++index;
+            ++matched;
+        } else if (matched > 0) {
+            // 构造前缀表时失配，也可以利用已求出的 prefix 回退。
+            matched = prefix[matched - 1];
+        } else {
+            prefix[index] = 0;
+            ++index;
+        }
+    }
+
+    // index 扫描主串，matched 表示当前已经匹配的模式串长度。
+    for (size_t index = 0, matched = 0; index < source.size();) {
+        ++compare_count;
+
+        if (source[index] == target[matched]) {
+            ++index;
+            ++matched;
+
+            if (matched == target.size()) {
+                matches.push_back(index - target.size());
+                // 找到一次完整匹配后继续回退，支持统计重叠匹配。
+                matched = prefix[matched - 1];
+            }
+        } else if (matched > 0) {
+            // 主串 index 不回退，只移动模式串匹配位置。
+            matched = prefix[matched - 1];
+        } else {
+            ++index;
+        }
+    }
+
+    return make_result(__func__, std::move(matches), compare_count, begin);
+}
+```
