+### 4.10 Boyer-Moore 核心实现
+
+Boyer-Moore 从模式串右端开始比较，失配时同时计算坏字符规则和好后缀规则的移动距离，并取较大值，从而尽可能跳过不可能匹配的位置。
+
+```cpp
+AlgoResult boyer_moore(std::string_view source, std::string_view target) {
+    const auto begin = Clock::now();
+    size_t comparison_count = 0;
+
+    if (target.empty()) {
+        return make_result(__func__, empty_target_matches(source.size()), comparison_count, begin);
+    }
+
+    std::vector<size_t> matches;
+    if (target.size() > source.size()) {
+        return make_result(__func__, std::move(matches), comparison_count, begin);
+    }
+
+    const size_t pattern_size = target.size();
+
+    // 坏字符表：记录每个字符在模式串中最后一次出现的位置。
+    // 若值为 pattern_size，说明该字符没有在模式串中出现。
+    std::array<size_t, 256> last_occurrence{};
+    last_occurrence.fill(pattern_size);
+    for (size_t index = 0; index < pattern_size; ++index) {
+        last_occurrence[static_cast<unsigned char>(target[index])] = index;
+    }
+
+    // 好后缀表：good_suffix_shift[i] 表示在位置 i 失配时应移动的距离。
+    std::vector<size_t> good_suffix_shift(pattern_size + 1, 0);
+    std::vector<size_t> border_position(pattern_size + 1, 0);
+    {
+        size_t index = pattern_size;
+        size_t border = pattern_size + 1;
+        border_position[index] = border;
+
+        while (index > 0) {
+            while (border <= pattern_size) {
+                ++comparison_count;
+                if (target[index - 1] == target[border - 1]) {
+                    break;
+                }
+                if (good_suffix_shift[border] == 0) {
+                    good_suffix_shift[border] = border - index;
+                }
+                border = border_position[border];
+            }
+            --index;
+            --border;
+            border_position[index] = border;
+        }
+
+        border = border_position[0];
+        for (size_t position = 0; position <= pattern_size; ++position) {
+            if (good_suffix_shift[position] == 0) {
+                good_suffix_shift[position] = border;
+            }
+            if (position == border) {
+                border = border_position[border];
+            }
+        }
+    }
+
+    size_t start = 0;
+    while (start <= source.size() - pattern_size) {
+        size_t remaining = pattern_size;
+
+        // 从右向左比较模式串。
+        while (remaining > 0) {
+            const size_t index = remaining - 1;
+            ++comparison_count;
+
+            if (source[start + index] == target[index]) {
+                --remaining;
+                continue;
+            }
+
+            const size_t last = last_occurrence[static_cast<unsigned char>(source[start + index])];
+            size_t bad_character_shift;
+
+            if (last == pattern_size) {
+                bad_character_shift = index + 1;
+            } else if (last < index) {
+                bad_character_shift = index - last;
+            } else {
+                bad_character_shift = 1;
+            }
+
+            const size_t good_shift = good_suffix_shift[index + 1];
+            start += std::max(bad_character_shift, good_shift);
+            break;
+        }
+
+        if (remaining == 0) {
+            matches.push_back(start);
+            start += good_suffix_shift[0];
+        }
+    }
+
+    return make_result(__func__, std::move(matches), comparison_count, begin);
+}
+```
