+### 4.11 Rabin-Karp 核心实现
+
+Rabin-Karp 使用滚动哈希快速筛选可能匹配的窗口。只有窗口哈希值与模式串哈希值相等时，才进行逐字符确认，因此可以减少大量不必要的字符比较。
+
+```cpp
+AlgoResult rabin_karp(std::string_view source, std::string_view target) {
+    const auto begin = Clock::now();
+    size_t compare_count = 0;
+
+    if (target.empty()) {
+        return make_result(__func__, empty_target_matches(source.size()), compare_count, begin);
+    }
+
+    std::vector<size_t> matches;
+    if (target.size() > source.size()) {
+        return make_result(__func__, std::move(matches), compare_count, begin);
+    }
+
+    constexpr uint64_t base = 256;
+    constexpr uint64_t modulus = 1'000'000'007;
+
+    uint64_t highest_base = 1;
+    uint64_t target_hash = 0;
+    uint64_t window_hash = 0;
+
+    // 计算模式串哈希和主串第一个窗口哈希。
+    for (size_t index = 0; index < target.size(); ++index) {
+        target_hash = (target_hash * base + static_cast<unsigned char>(target[index])) % modulus;
+        window_hash = (window_hash * base + static_cast<unsigned char>(source[index])) % modulus;
+
+        if (index + 1 < target.size()) {
+            highest_base = (highest_base * base) % modulus;
+        }
+    }
+
+    for (size_t start = 0; start + target.size() <= source.size(); ++start) {
+        // 哈希相等只是“可能匹配”，仍需逐字符确认以处理哈希冲突。
+        if (window_hash == target_hash) {
+            size_t matched = 0;
+            while (matched < target.size()) {
+                ++compare_count;
+                if (source[start + matched] != target[matched]) {
+                    break;
+                }
+                ++matched;
+            }
+
+            if (matched == target.size()) {
+                matches.push_back(start);
+            }
+        }
+
+        // 滚动更新窗口哈希：移除最左字符，加入右侧新字符。
+        if (start + target.size() < source.size()) {
+            const uint64_t leading = static_cast<unsigned char>(source[start]);
+            const uint64_t trailing = static_cast<unsigned char>(source[start + target.size()]);
+            window_hash = (window_hash + modulus - (leading * highest_base) % modulus) % modulus;
+            window_hash = (window_hash * base + trailing) % modulus;
+        }
+    }
+
+    return make_result(__func__, std::move(matches), compare_count, begin);
+}
